"places": [{"position": 0, "label": null, "address": null, "city": "Boston", "state": "MA", "postal_code": null}], "tier": "A"}, {"name": "Adaptive Sports New England", "code": "ASNE", "description": "[adaptivesportsne.org](https://adaptivesportsne.org/)", "city": "Boston", "state": "MA", "aliases": [], "places": [{"position": 0, "label": null, "address": "89 South Street, Suite 603", "city": "Boston", "state": "MA", "postal_code": "02111"}, {"position": 1, "label": null, "address": null, "city": "Boston", "state": "MA", "postal_code": null}], "tier": "B"}, {"name": "Spaulding Rehabilitation Adaptive Sports Centers", "code": "SRAS", "description": "[sasc.spauldingrehab.org](https://sasc.spauldingrehab.org/)", "city": "Charlestown", "state": "MA", "aliases": [], "places": [{"position": 0, "label": "Boston", "address": "300 1st Ave", "city": "Charlestown", "state": "MA", "postal_code": "02129"}, {"position": 1, "label": "Boston", "address": null, "city": "Boston", "state": "MA", "postal_code": null}, {"position": 2, "label": "North Shore", "address": "35 Congress Street suite 211", "city": "Salem", "state": "MA", "postal_code": "01970"}, {"position": 3, "label": "Cape Cod", "address": null, "city": "Brewster", "state": "MA", "postal_code": "02631"}], "tier": "B"}, {"name": "Piers Park Sailing", "code": "PPS", "description": "[piersparksailing.org](https://piersparksailing.org/adaptive/adaptive-sailing)", "city": "Boston", "state": "MA", "aliases": [], "places": [{"position": 0, "label": null, "address": null, "city": "Boston", "state": "MA", "postal_code": null}], "tier": "A"}, {"name": "Access 2 Adventure", "code": "AAA", "description": "[usopc.org](https://www.usopc.org/paralympic-sport-development/getting-started/find-a-club/rhode-island)", "city": "Little Compton", "state": "RI", "aliases": [], "places": [{"position": 0, "label": null, "address": "45 Indian Road", "city": "Little Compton", "state": "RI", "postal_code": "02837"}], "tier": "B"}, {"name": "Cape Cod Curling Club", "code": "CCCC", "description": "[capecodcurling.org](https://www.capecodcurling.org)", "city": "Falmouth", "state": "MA", "aliases": [], "places": [{"position": 0, "label": null, "address": null, "city": "Falmouth", "state": "MA", "postal_code": "02541"}], "tier": "B"}]$hub$::jsonb) loop
    continue when exists (
      select 1 from public.organizations o
       where lower(o.name) = lower(item ->> 'name')
          or lower(item ->> 'name') = any (select lower(a) from unnest(o.aliases) a)
    );
    code := item ->> 'code';
    tries := 0;
    while exists (select 1 from public.organizations o where o.short_code = code) loop
      tries := tries + 1;
      code := left(item ->> 'code', 2) || chr(65 + (tries / 26) % 26) || chr(65 + tries % 26);
    end loop;
    insert into public.organizations (short_code, name, city, state, description, aliases)
    values (code, item ->> 'name', item ->> 'city', item ->> 'state', item ->> 'description',
            array(select jsonb_array_elements_text(item -> 'aliases')))
    returning id into org;
    insert into public.organization_places
      (organization_id, position, label, address, city, state, postal_code)
    select org, (p ->> 'position')::integer, p ->> 'label', p ->> 'address', p ->> 'city',
           p ->> 'state', p ->> 'postal_code'
      from jsonb_array_elements(item -> 'places') p;
  end loop;
end;
$$;

-- Organizations here with no location, where the hub shows one.
insert into public.organization_places (organization_id, position, label, address, city, state, postal_code)
select o.id, 0, null, null, 'Los Angeles', 'CA', '90024-0856'
  from public.organizations o
 where o.name = 'The Unrecables'
   and not exists (select 1 from public.organization_places x where x.organization_id = o.id);
update public.organizations set city = coalesce(city, 'Los Angeles'), state = coalesce(state, 'CA')
 where name = 'The Unrecables';
